<?php
namespace Certloom\Application\Issuance;

use Certloom\Application\Contract\BulkRecipientResolverInterface;
use Certloom\Application\Contract\JobHandlerInterface;
use Certloom\Application\Contract\JobRepositoryInterface;
use Certloom\Application\Job\JobSliceResult;
use Certloom\Application\Rendering\CanonicalJson;
use Certloom\Domain\Job\JobStates;
use Certloom\Domain\Job\JobTypes;
use Certloom\Infrastructure\Files\PrivateJobFileStore;
use Certloom\Infrastructure\Issuance\BulkIssuancePlanStore;
use Certloom\Infrastructure\Issuance\BulkRecipientResolver;

/** Bounded per-row commit using the exact reviewed Manual Issuance truth path. */
final class BulkIssuanceCommitJobHandler implements JobHandlerInterface {
	const MAX_ERRORS=100;
	private $jobs; private $plans; private $issuance; private $resolver; private $files; private $json; private $batch_size;
	public function __construct(JobRepositoryInterface $jobs,?BulkIssuancePlanStore $plans=null,?ManualIssuanceService $issuance=null,?BulkRecipientResolverInterface $resolver=null,?PrivateJobFileStore $files=null,?CanonicalJson $json=null,$batch_size=25){$this->jobs=$jobs;$this->files=$files?:new PrivateJobFileStore();$this->json=$json?:new CanonicalJson();$this->plans=$plans?:new BulkIssuancePlanStore($this->files,$this->json);$this->issuance=$issuance?:new ManualIssuanceService();$this->resolver=$resolver?:new BulkRecipientResolver();$this->batch_size=max(1,min(100,absint($batch_size)));}
	public function handle(array $job,$worker_token){$payload=is_array($job['payload']??null)?$job['payload']:array();$prekey=(string)($payload['preflight_job_key']??'');$pre=$this->jobs->find($prekey);if(is_wp_error($pre)){return $pre;}if(!is_array($pre)||JobTypes::BULK_ISSUANCE_PREFLIGHT!==(string)($pre['job_type']??'')){return new \WP_Error('certloom_bulk_preflight_invalid',__('The reviewed Bulk Issuance job is unavailable.','certloom'));}if(!in_array((string)($pre['status']??''),array(JobStates::SUCCEEDED,JobStates::PARTIALLY_SUCCEEDED),true)){return new \WP_Error('certloom_bulk_preflight_incomplete',__('Bulk Issuance review must finish before commit.','certloom'));}if(absint($pre['owner_user_id']??0)!==absint($job['owner_user_id']??0)){return new \WP_Error('certloom_bulk_owner_mismatch',__('This Bulk Issuance review belongs to another administrator.','certloom'));}
		$pr=is_array($pre['result']??null)?$pre['result']:array();$expected=(string)($payload['review_fingerprint']??'');if(empty($pr['ready_for_issue'])||!preg_match('/^[a-f0-9]{64}$/',$expected)||!hash_equals((string)($pr['review_fingerprint']??''),$expected)){return new \WP_Error('certloom_bulk_review_stale',__('The Bulk Issuance commit does not match the reviewed batch. Review the CSV again.','certloom'));}
		$result=is_array($job['result']??null)?$job['result']:array();$plan=(string)($pr['plan_path']??'');if(!empty($result['commit_complete'])){return $this->finish_cleanup($result,$plan,$prekey,$expected);}
		$sha=$this->plans->sha256($plan);if(is_wp_error($sha)){return $sha;}if(!hash_equals((string)($pr['plan_sha256']??''),$sha)){return new \WP_Error('certloom_bulk_plan_changed',__('The protected Bulk Issuance review plan changed after review.','certloom'));}
		$offset=absint($result['plan_offset']??0);$summary=$this->summary($result['summary']??array());$slice=$this->plans->read_slice($plan,$offset,$this->batch_size);if(is_wp_error($slice)){return $slice;}
		foreach($slice['entries'] as $entry){$row=absint($entry['row_number']??0);$summary['processed']++;$request=$this->resolver->resolve((array)($entry['request']??array()));if(is_wp_error($request)){$this->err($summary,$row,$request);continue;}$review=$this->issuance->revalidate_review($request);if(is_wp_error($review)){$this->err($summary,$row,$review);continue;}if(!hash_equals((string)($entry['review_fingerprint']??''),(string)$review['review_fingerprint'])){$this->err($summary,$row,new \WP_Error('certloom_bulk_row_review_stale',__('This row changed after Bulk Issuance review and was not issued.','certloom')));continue;}
			try{$idem=$this->json->hash(array('source'=>'bulk_admin','preflight_job_key'=>$prekey,'row_number'=>$row,'review_fingerprint'=>(string)$review['review_fingerprint']));}catch(\Throwable $e){$this->err($summary,$row,new \WP_Error('certloom_bulk_row_idempotency_failed',__('Certloom could not create the row idempotency key.','certloom')));continue;}$receipt=$this->issuance->issue_reviewed_for_source($request,(string)$review['review_fingerprint'],absint($job['owner_user_id']??0),'bulk_admin','bulk:'.$prekey.':row:'.$row,$idem,'bulk_issue');if(is_wp_error($receipt)){$this->err($summary,$row,$receipt);continue;}$summary['succeeded']++;if(!empty($receipt['idempotent_replay'])){$summary['idempotent_replays']++;}if(count($summary['receipts'])<100){$summary['receipts'][]=array('row'=>$row,'series_id'=>absint($receipt['series_id']??0),'version_id'=>absint($receipt['version_id']??0),'display_number'=>(string)($receipt['display_number']??''),'public_id'=>(string)($receipt['public_id']??''),'idempotent_replay'=>!empty($receipt['idempotent_replay']));}}
		$next=array('plan_offset'=>absint($slice['offset']),'summary'=>$summary);if(empty($slice['complete'])){return JobSliceResult::progress($summary['processed'],'bulk_issue',$next);}
		/* Save the terminal row cursor before deleting the plan, making a crash during cleanup replay-safe. */
		$next['commit_complete']=true;return JobSliceResult::progress($summary['processed'],'bulk_cleanup',$next);}
	private function finish_cleanup(array $result,$plan,$prekey,$expected){$summary=$this->summary($result['summary']??array());if(''!==(string)$plan&&$this->files->owns($plan)){$deleted=$this->files->delete($plan);if(is_wp_error($deleted)||false===$deleted){$summary['warnings'][]=__('Bulk Issuance finished, but its protected review plan could not be removed immediately. Retention cleanup will retry.','certloom');}}$final=array('preflight_job_key'=>(string)$prekey,'review_fingerprint'=>(string)$expected,'summary'=>$summary);return $summary['failed']?JobSliceResult::partially_succeeded($final,$summary['processed']):JobSliceResult::succeeded($final,$summary['processed']);}
	private function summary($s){$s=is_array($s)?$s:array();return array('processed'=>absint($s['processed']??0),'succeeded'=>absint($s['succeeded']??0),'failed'=>absint($s['failed']??0),'idempotent_replays'=>absint($s['idempotent_replays']??0),'error_details'=>array_slice(is_array($s['error_details']??null)?$s['error_details']:array(),0,self::MAX_ERRORS),'receipts'=>array_slice(is_array($s['receipts']??null)?$s['receipts']:array(),0,100),'warnings'=>array_slice(is_array($s['warnings']??null)?$s['warnings']:array(),0,20));}
	private function err(array &$s,$row,\WP_Error $e){$s['failed']++;if(count($s['error_details'])<self::MAX_ERRORS){$s['error_details'][]=array('row'=>absint($row),'code'=>sanitize_key($e->get_error_code()),'message'=>sanitize_text_field($e->get_error_message()));}}
}
